// Loads the columnar data and the config generated by serialize_json.py.
// Shapes are validated on the Python side, so the JSON is only cast here.

import config from '#lib/data/config.json';
// Imported as a string so that only the packed columns outlive the parsing
import raw from '#lib/data/data.json?raw';
import { buildDataset, type Config, type RawData } from '#lib/metrics.ts';

export const Data = buildDataset(JSON.parse(raw) as RawData, config as Config);
